import{c as t,Q as a,j as i,m as n}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Visual Instruction Tuning","description":"","frontmatter":{"url":"https://arxiv.org/abs/2304.08485","title":"Visual Instruction Tuning","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2304.08485,"authors":["Haotian Liu","Chunyuan Li","Qingyang Wu","Yong Jae Lee"],"pdf_path":"pdfs/2304.08485.pdf","published_date":"2023-01-01T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2023-04-17-llava-visual-instruction-tuning-2304-08485.md","filePath":"research/papers/2023-04-17-llava-visual-instruction-tuning-2304-08485.md","lastUpdated":1785909234000}'),o={name:"research/papers/2023-04-17-llava-visual-instruction-tuning-2304-08485.md"};function r(s,e,l,u,d,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="visual-instruction-tuning" tabindex="-1">Visual Instruction Tuning <a class="header-anchor" href="#visual-instruction-tuning" aria-label="Permalink to &quot;Visual Instruction Tuning&quot;">​</a></h1><p><strong>Authors:</strong> Haotian Liu, Chunyuan Li, Qingyang Wu, Yong Jae Lee <strong>Year:</strong> 2023 <strong>Venue:</strong> NeurIPS 2023 (Oral) <strong>ArXiv:</strong> <a href="https://arxiv.org/abs/2304.08485" target="_blank" rel="noreferrer">https://arxiv.org/abs/2304.08485</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>In this paper, we present the first attempt to use language-only GPT-4 to generate multimodal language-image instruction-following data. By instruction tuning on such generated data, we introduce LLaVA (Large Language and Vision Assistant): an end-to-end trained large multimodal model that connects a vision encoder and LLM for general-purpose visual and language understanding. Our early experiments show that LLaVA demonstrates impressive multimodel chat abilities, sometimes exhibiting the behaviours of multimodal GPT-4 on unseen images/instructions, and yields a 85.1% relative score compared with GPT-4 on a synthetic multimodal instruction-following dataset. When fine-tuned on Science QA, the synergy of LLaVA and GPT-4 achieves a new state-of-the-art accuracy of 92.53%. We make GPT-4 generated visual instruction tuning data, our model and code base publicly available.</p><hr><h2 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h2><ul><li><strong>First use of language-only GPT-4 to generate multimodal language-image instruction-following data</strong>, establishing a new paradigm for visual instruction tuning that sidesteps costly human annotation</li><li><strong>LLaVA architecture</strong> connecting CLIP ViT-L/14 vision encoder with Vicuna LLM via a trainable linear projection layer for end-to-end multimodal understanding</li><li>Achieves <strong>85.1% relative score vs. GPT-4</strong> on a synthetic multimodal instruction-following benchmark and <strong>92.53% on ScienceQA</strong> (SOTA at time of publication)</li><li><strong>Open-source release</strong> of generated instruction data, model weights, and training code enabling broad community research and reproducibility</li><li><strong>NeurIPS 2023 Oral</strong> — demonstrated that instruction-tuned multimodal models trained on synthetic data can rival closed-source systems</li><li>Pioneered the concept of converting image-text pairs into instruction-following format using a capable language model as the data generator</li><li>Established the viability of simple connector modules (linear projection) between off-the-shelf vision and language backbones</li></ul><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>LLaVA connects a pre-trained CLIP visual encoder (ViT-L/14) with a large language model (Vicuna) through a trainable linear projection matrix. The vision encoder produces visual features from an input image, which are projected into the LLM&#39;s word embedding space. This allows the LLM to treat visual tokens identically to text tokens during generation.</p><p>The key innovation in data generation is using GPT-4 (text-only) to convert image-text pairs (sourced from CC3M/COCO captions) into instruction-following format. By providing GPT-4 with image captions and detected bounding box annotations as text context, the authors prompt it to generate conversational QA pairs, detailed descriptions, and complex reasoning questions — three data types that cover a spectrum from factual to open-ended visual understanding.</p><p>Training proceeds in two stages: (1) pre-training where only the projection layer is updated to align visual features with LLM token embeddings using filtered CC-595K image-text pairs, and (2) fine-tuning end-to-end (projection + LLM, vision encoder frozen) on the 158K generated instruction-following data plus ScienceQA for task-specific scenarios.</p><hr><h2 id="main-results" tabindex="-1">Main Results <a class="header-anchor" href="#main-results" aria-label="Permalink to &quot;Main Results&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Benchmark</th><th>LLaVA Score</th></tr></thead><tbody><tr><td>Synthetic multimodal instruction-following (vs. GPT-4)</td><td>85.1% relative</td></tr><tr><td>ScienceQA (with GPT-4 judge)</td><td>92.53% accuracy (SOTA)</td></tr></tbody></table><p>LLaVA exhibits emergent multimodal chat behaviors on unseen images, including detailed scene description, OCR-level reading, and multi-step visual reasoning — capabilities not explicitly trained for but arising from instruction tuning on diverse synthetic data.</p><hr><h2 id="limitations-future-work" tabindex="-1">Limitations &amp; Future Work <a class="header-anchor" href="#limitations-future-work" aria-label="Permalink to &quot;Limitations &amp; Future Work&quot;">​</a></h2><ul><li>The linear projection connector is simple; more expressive connectors may better bridge the visual-language gap (addressed in LLaVA-1.5)</li><li>Instruction data quality is bounded by the text-only GPT-4&#39;s ability to reason from captions/boxes rather than actual image pixels</li><li>Hallucination remains a known failure mode when visual evidence is ambiguous or absent</li><li>Evaluation benchmarks at time of publication were limited; subsequent work developed more rigorous multimodal benchmarks (MMBench, MME, etc.)</li><li>The 7B/13B scale may be insufficient for tasks requiring deep world knowledge or fine-grained visual reasoning</li></ul><hr><h2 id="why-this-matters-for-ai-practitioners" tabindex="-1">Why This Matters for AI Practitioners <a class="header-anchor" href="#why-this-matters-for-ai-practitioners" aria-label="Permalink to &quot;Why This Matters for AI Practitioners&quot;">​</a></h2><p>LLaVA established that <strong>high-quality synthetic instruction data can bootstrap competitive multimodal models</strong> without expensive human annotation pipelines. The architecture (vision encoder → lightweight connector → frozen/fine-tuned LLM) became the dominant paradigm for open-source multimodal models. The open release directly enabled a wave of follow-on work (LLaVA-1.5, InstructBLIP, MiniGPT-4) and established reproducible baselines the community could build on.</p><p>For practitioners, LLaVA demonstrates: (1) GPT-4 as a scalable data labeler for domains where annotation is expensive, (2) the power of instruction tuning over simple captioning objectives, and (3) that simple connector modules between strong frozen backbones are a practical and efficient path to multimodal capability.</p>',24)])])}const m=t(o,[["render",r]]);export{g as __pageData,m as default};
